class Solution {
public:
    int destroyTargets(std::vector<int>& nums, int space) {
        std::unordered_map<int, int> counts;
        std::unordered_map<int, int> min_num;
        for (int x : nums) {
            int rem = x % space;
            counts[rem]++;
            if (min_num.find(rem) == min_num.end() || x < min_num[rem]) {
                min_num[rem] = x;
            }
        }
        int max_cnt = 0;
        for (const auto& pair : counts) {
            if (pair.second > max_cnt) max_cnt = pair.second;
        }
        int ans = INT_MAX;
        for (const auto& pair : counts) {
            if (pair.second == max_cnt) {
                ans = std::min(ans, min_num[pair.first]);
            }
        }
        return ans;
    }
};

class Solution {
    public int destroyTargets(int[] nums, int space) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> minNum = new java.util.HashMap<>();
        for (int x : nums) {
            int rem = x % space;
            counts.put(rem, counts.getOrDefault(rem, 0) + 1);
            if (!minNum.containsKey(rem) || x < minNum.get(rem)) {
                minNum.put(rem, x);
            }
        }
        int maxCnt = 0;
        for (int c : counts.values()) {
            if (c > maxCnt) maxCnt = c;
        }
        int ans = Integer.MAX_VALUE;
        for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == maxCnt) {
                ans = Math.min(ans, minNum.get(entry.getKey()));
            }
        }
        return ans;
    }
}

var destroyTargets = function(nums, space) {
    const counts = new Map();
    const minNum = new Map();
    for (const x of nums) {
        const rem = x % space;
        counts.set(rem, (counts.get(rem) || 0) + 1);
        if (!minNum.has(rem) || x < minNum.get(rem)) {
            minNum.set(rem, x);
        }
    }
    let maxCnt = 0;
    for (const c of counts.values()) {
        if (c > maxCnt) maxCnt = c;
    }
    let ans = Infinity;
    for (const [rem, c] of counts.entries()) {
        if (c === maxCnt) {
            ans = Math.min(ans, minNum.get(rem));
        }
    }
    return ans;
};
